// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _targetBase) public {
        vm.assume(_value > 0);
        vm.assume(_targetBase != address(c));
        vm.assume(_targetBase != address(0));

        Reverter reverter = new Reverter();
        vm.deal(address(c), _value);
        bool success = false;
        try c.sendMoney(address(reverter), _value) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
